CREATE TABLE "t04_filing_project" (
  "id" INTEGER PRIMARY KEY,
  "source_file" TEXT,
  "source_sheet" TEXT,
  "excel_row" INTEGER,
  "serial_no" INTEGER,
  "project_name" TEXT,
  "project_type" TEXT,
  "planned_scale" TEXT,
  "construction_location" TEXT,
  "booster_station_coordinate" TEXT,
  "point_coordinate" TEXT,
  "owner_unit" TEXT,
  "total_investment_hundred_million_yuan" REAL,
  "planned_start_date_raw" TEXT,
  "planned_grid_operation_date_raw" TEXT,
  "contact" TEXT,
  "remarks" TEXT,
  "planned_start_month" TEXT,
  "planned_start_date_parse_status" TEXT,
  "planned_grid_operation_month" TEXT,
  "planned_grid_operation_date_parse_status" TEXT,
  "district_name" TEXT,
  "district_parse_status" TEXT
);
